    css: '@scope (.header-simple) to ([class*="loam-"]) {\n  :scope {\n    align-items: center;\n    border-block-end: 1px solid var(--loam-color-line);\n    container-type: inline-size;\n    display: block flex;\n    flex-wrap: wrap;\n    gap: var(--loam-space-sm) var(--loam-space-lg);\n    padding-block: var(--loam-space-md);\n  }\n\n  a.brand {\n    align-items: center;\n    color: var(--loam-color-fg-strong);\n    display: inline flex;\n    font-family: var(--loam-font-display);\n    font-size: var(--loam-text-lg);\n    font-weight: 700;\n    gap: var(--loam-space-xs);\n    letter-spacing: -0.02em;\n    text-decoration: none;\n\n    svg {\n      block-size: 1.25em;\n      inline-size: 1.25em;\n    }\n  }\n\n  div.actions {\n    align-items: center;\n    display: block flex;\n    gap: var(--loam-space-sm);\n    margin-inline-start: auto;\n  }\n}\n\n@scope (.header-simple .loam-Nav) to ([class*="loam-"]) {\n  :scope {\n    /* A style query is answered by ancestors, so the edge is declared here,\n       never on the link. */\n    --loam-nav-current-edge: block-end;\n  }\n\n  ul.row {\n    display: block flex;\n    flex-wrap: wrap;\n    gap: var(--loam-space-xs);\n  }\n\n  @container (inline-size < 48rem) {\n    :scope {\n      flex-basis: 100%;\n      order: 1;\n    }\n  }\n}\n',
